import { z } from "zod";

// Independent execution receipts, not generated by the gate or its observer.
const receipts: { name: string; token: string }[] = [];

const Request = z.object({ id: z.union([z.string(), z.number()]).optional(), method: z.string(), params: z.unknown().optional() });

export function mcpFixture(port = 0, hostname = "127.0.0.1") {
  return Bun.serve({ hostname, port, async fetch(request) {
    if (new URL(request.url).pathname === "/receipts") return Response.json(receipts);

    if (request.method === "DELETE") return new Response(null, { status: 200 });

    if (request.method !== "POST") return new Response(null, { status: 405 });
    const body = Request.parse(await request.json());

    if (body.id === undefined) return new Response(null, { status: 202 });
    const reply = <T,>(result: T) => Response.json({ jsonrpc: "2.0", id: body.id, result });

    if (body.method === "initialize") return reply({
      protocolVersion: "2024-11-05", serverInfo: { name: "receipt-fixture", version: "1" }, capabilities: { tools: {} },
    });

    if (body.method === "tools/list") return reply({ tools: ["resolve-library-id", "query-docs"].map((name) => ({
      name, description: "Records a synthetic execution token", inputSchema: { type: "object", properties: { token: { type: "string" } }, required: ["token"] },
    })) });

    if (body.method === "tools/call") {
      const call = z.object({ name: z.string(), arguments: z.object({ token: z.string() }) }).parse(body.params);
      receipts.push({ name: call.name, token: call.arguments.token });

      return reply({ content: [{ type: "text", text: "Execution recorded." }] });
    }

    return Response.json({ jsonrpc: "2.0", id: body.id, error: { code: -32601, message: "Unknown method" } });
  } });
}

if (import.meta.main) mcpFixture(3002, "0.0.0.0");
